insert into public.interviews (id, user_id, category, difficulty, scheduled_at, status, questions, answers, started_at, submitted_at)
values ('22222222-2222-4222-8222-222222222221', '11111111-1111-4111-8111-111111111111', 'frontend', 'intermediate', (date_trunc('day', now() at time zone 'UTC') - interval '18 days' + interval '5.5 hours') at time zone 'UTC', 'completed',
  '[{"prompt":"Walk me through what happens between calling setState in React and the updated UI appearing on screen.","topic":"Rendering and reconciliation"},{"prompt":"A list of 2,000 rows scrolls badly. How would you find the cause, and what would you try first?","topic":"Performance"},{"prompt":"When would you reach for useReducer or a global store instead of useState, and what does each cost you?","topic":"State management"},{"prompt":"How do you make a custom dropdown usable with a keyboard and a screen reader?","topic":"Accessibility"},{"prompt":"Explain how a cross-site scripting attack works and the layers you would use to defend a React app.","topic":"Web security"}]'::jsonb,
  '{"0":"React schedules a re-render, runs the component again, diffs the new virtual DOM against the old one and updates only what changed in the real DOM. Several setState calls in one event are batched into a single render.","1":"I would open the React Profiler to see which rows re-render, then memoise the row component and virtualise the list so only visible rows are in the DOM.","2":"useState is fine for local state. When many components need the same data I would use Context or Zustand. useReducer helps when the next state depends on several rules.","3":"Use a button with aria-haspopup, arrow keys to move between options, Escape to close, and move focus back to the button afterwards.","4":"XSS injects scripts into the page. React escapes values by default, so I avoid dangerouslySetInnerHTML and sanitise any HTML I must render."}'::jsonb,
  (date_trunc('day', now() at time zone 'UTC') - interval '18 days' + interval '5.5 hours') at time zone 'UTC', (date_trunc('day', now() at time zone 'UTC') - interval '18 days' + interval '5.5 hours' + interval '38 minutes') at time zone 'UTC');

insert into public.feedbacks (id, interview_id, user_id, overall_score, result, model, created_at)
values ('33333333-3333-4333-8333-333333333331', '22222222-2222-4222-8222-222222222221', '11111111-1111-4111-8111-111111111111', 5.6, '{"scores":{"technicalAccuracy":6,"depth":4.8,"problemSolving":5.5,"communication":6.5,"structure":5.2},"summary":"A sound foundation with correct vocabulary, but answers stay at definition level. You rarely explain why something works or what it costs, which keeps the depth and structure scores low.","strengths":["You name the right tools (Profiler, memoisation, virtualisation) without prompting.","Your rendering answer was accurate and used correct terminology.","Answers are readable and stay on topic."],"weaknesses":["Answers stop at the first correct idea instead of explaining the mechanism or trade-offs.","Accessibility and security answers were thin and missed key techniques.","No concrete example from your own projects in any answer."],"recommendations":["For each answer, add one sentence starting with \"The trade-off is\".","Prepare one real example from a project for rendering, state and performance.","Read the WAI-ARIA authoring practices for listbox and dialog."],"perQuestion":[{"index":0,"score":6.5,"feedback":"Correct outline of render and reconcile. You did not mention the commit phase or when effects run, which is where interviewers usually probe.","betterAnswer":"State is a request to re-render. React re-runs the component, reconciles the result with the previous tree, commits the minimal DOM changes, then runs effects."},{"index":1,"score":6,"feedback":"Good first move with the Profiler. Say what you would look for, such as wasted renders from unstable props, and why virtualisation helps.","betterAnswer":"Profile first to confirm renders are the cause, fix unstable props with memo and stable callbacks, then virtualise so the DOM stays small."},{"index":2,"score":5.5,"feedback":"You named the right tools but not the trade-offs. When does Context cause extra renders? What does a store add?","betterAnswer":"useState for local state, useReducer for complex transitions, and a store when many distant components share state and need selective subscriptions."},{"index":3,"score":5,"feedback":"Correct ideas, but too brief. Name the ARIA roles, explain focus management, and say how you would test it with a screen reader.","betterAnswer":"Follow the WAI-ARIA listbox pattern: roles, aria-expanded, arrow-key navigation, Escape to close, and visible focus."},{"index":4,"score":5.5,"feedback":"Right instincts. Add Content-Security-Policy and HttpOnly cookies to show defence in depth.","betterAnswer":"Escape output, avoid raw HTML injection, sanitise unavoidable HTML, set a strict CSP and keep tokens in HttpOnly cookies."}],"overallScore":5.6}'::jsonb, 'demo-seed', (date_trunc('day', now() at time zone 'UTC') - interval '18 days' + interval '5.5 hours' + interval '40 minutes') at time zone 'UTC');

insert into public.interviews (id, user_id, category, difficulty, scheduled_at, status, questions, answers, started_at, submitted_at)
values ('22222222-2222-4222-8222-222222222222', '11111111-1111-4111-8111-111111111111', 'backend', 'intermediate', (date_trunc('day', now() at time zone 'UTC') - interval '11 days' + interval '6.5 hours') at time zone 'UTC', 'completed',
  '[{"prompt":"Design the REST endpoints for booking a time slot. Which verbs, status codes and error shapes would you use?","topic":"REST design"},{"prompt":"Where would you keep a login session, a JWT in localStorage or an HttpOnly cookie, and why?","topic":"Authentication"},{"prompt":"Two users try to book the same slot at the same instant. How do you guarantee only one succeeds?","topic":"Data integrity"},{"prompt":"A query that was fast last month now takes seconds. How do you diagnose it, and what are your usual fixes?","topic":"SQL and indexing"},{"prompt":"Your service calls a third-party API that sometimes times out. How do you keep your own API healthy?","topic":"Resilience"}]'::jsonb,
  '{"0":"POST /bookings to create, GET /bookings/:id to read, PATCH to change status and DELETE to cancel. I would return 201 with a Location header, 404 for missing, 409 for a taken slot and 422 for invalid input, with the same JSON error shape everywhere.","1":"An HttpOnly cookie, because JavaScript cannot read it so XSS cannot steal the token. localStorage is easy to read from any injected script. I would add SameSite and a CSRF header check.","2":"Put a unique constraint on the slot in the database. The second insert fails with a unique violation and I map it to a 409. Checking first in code is not enough because two requests can pass the check together.","3":"Run EXPLAIN ANALYZE, look for a sequential scan, then add an index on the filtered column. Check whether the table grew or statistics are stale.","4":"Set a timeout, retry with backoff only for safe requests, and use a circuit breaker so a slow dependency does not exhaust my threads."}'::jsonb,
  (date_trunc('day', now() at time zone 'UTC') - interval '11 days' + interval '6.5 hours') at time zone 'UTC', (date_trunc('day', now() at time zone 'UTC') - interval '11 days' + interval '6.5 hours' + interval '38 minutes') at time zone 'UTC');

insert into public.feedbacks (id, interview_id, user_id, overall_score, result, model, created_at)
values ('33333333-3333-4333-8333-333333333332', '22222222-2222-4222-8222-222222222222', '11111111-1111-4111-8111-111111111111', 6.5, '{"scores":{"technicalAccuracy":6.8,"depth":5.9,"problemSolving":6.2,"communication":7,"structure":6.4},"summary":"A clear step up. Your database-integrity answer was excellent and your API design was consistent. Query tuning and resilience answers named the right ideas but need more detail about how and when.","strengths":["You put the double-booking guarantee in the database, which is the correct place.","Consistent API design with correct status codes.","Clear, well-organised communication."],"weaknesses":["Performance tuning stayed at \"add an index\" without explaining reading a query plan.","Resilience answer did not cover when retries are harmful.","Few numbers or measurements to back claims."],"recommendations":["Practise reading EXPLAIN output on a table with a million rows.","Learn idempotency keys and when retries cause duplicate work.","Add one measurable result to each answer."],"perQuestion":[{"index":0,"score":7.5,"feedback":"Clear resource design with correct status codes and a consistent error shape. Mention idempotency for retries to reach full marks.","betterAnswer":"Resource-oriented routes, 201 plus Location on create, 409 for conflicts, 422 for validation, and idempotency keys for unsafe retries."},{"index":1,"score":7,"feedback":"Good reasoning about XSS and the SameSite/CSRF add-on. Strengthen it by mentioning token expiry and rotation.","betterAnswer":"HttpOnly, Secure, SameSite cookie with short expiry; add a CSRF defence because cookies are sent automatically."},{"index":2,"score":7.5,"feedback":"Excellent: you identified the race condition and put the guarantee in the database. This is the strongest answer.","betterAnswer":"Enforce uniqueness with a database constraint, handle the violation as a 409, and keep any pre-check as a UX nicety only."},{"index":3,"score":5.5,"feedback":"The method is right but shallow. Explain how to read the plan, and mention composite indexes and the write cost of indexing.","betterAnswer":"Read the plan, add a composite index matching the filter and sort, and weigh read gains against write overhead."},{"index":4,"score":6,"feedback":"You listed the right patterns. Explain when retries make things worse and what you would monitor.","betterAnswer":"Timeouts, bounded retries with jitter, a circuit breaker, and metrics on error rate and latency."}],"overallScore":6.5}'::jsonb, 'demo-seed', (date_trunc('day', now() at time zone 'UTC') - interval '11 days' + interval '6.5 hours' + interval '40 minutes') at time zone 'UTC');

insert into public.interviews (id, user_id, category, difficulty, scheduled_at, status, questions, answers, started_at, submitted_at)
values ('22222222-2222-4222-8222-222222222223', '11111111-1111-4111-8111-111111111111', 'frontend', 'intermediate', (date_trunc('day', now() at time zone 'UTC') - interval '4 days' + interval '7.5 hours') at time zone 'UTC', 'completed',
  '[{"prompt":"Walk me through what happens between calling setState in React and the updated UI appearing on screen.","topic":"Rendering and reconciliation"},{"prompt":"A list of 2,000 rows scrolls badly. How would you find the cause, and what would you try first?","topic":"Performance"},{"prompt":"When would you reach for useReducer or a global store instead of useState, and what does each cost you?","topic":"State management"},{"prompt":"How do you make a custom dropdown usable with a keyboard and a screen reader?","topic":"Accessibility"},{"prompt":"Explain how a cross-site scripting attack works and the layers you would use to defend a React app.","topic":"Web security"}]'::jsonb,
  '{"0":"Calling setState queues an update. React batches it, re-renders the component, reconciles the new tree against the previous one using keys and element types, commits the minimal DOM mutations, then runs layout effects and passive effects. Rendering is pure; side effects belong in effects.","1":"I would record a Profiler trace to confirm the rows are re-rendering, then stabilise props, wrap the row in memo, and use windowing so only about twenty rows are mounted. I would measure frame time before and after instead of guessing.","2":"Local state stays in useState. Once several distant components need it I prefer a small store like Zustand with selectors so only subscribers re-render. Context re-renders every consumer on any change, so it suits rarely changing values like auth.","3":"I would follow the ARIA listbox pattern: a button with aria-expanded, options with role=option, arrow keys, Home and End, type-ahead, Escape to close and focus restored to the trigger. Then I would test with a screen reader.","4":"An attacker injects script that runs with the page origin. React escapes by default, so the risk is dangerouslySetInnerHTML, unsafe URLs and third-party scripts. I sanitise HTML, set a strict CSP, keep tokens in HttpOnly cookies and audit dependencies."}'::jsonb,
  (date_trunc('day', now() at time zone 'UTC') - interval '4 days' + interval '7.5 hours') at time zone 'UTC', (date_trunc('day', now() at time zone 'UTC') - interval '4 days' + interval '7.5 hours' + interval '38 minutes') at time zone 'UTC');

insert into public.feedbacks (id, interview_id, user_id, overall_score, result, model, created_at)
values ('33333333-3333-4333-8333-333333333333', '22222222-2222-4222-8222-222222222223', '11111111-1111-4111-8111-111111111111', 7.4, '{"scores":{"technicalAccuracy":7.6,"depth":6.9,"problemSolving":7.2,"communication":7.8,"structure":7.5},"summary":"A strong, well-structured session. Answers now explain mechanisms and trade-offs, and you back claims with measurement. The remaining gap is depth on edge cases and naming one more advanced technique per answer.","strengths":["You explain why, not only what, and you state trade-offs.","You propose measuring before optimising.","Answers are well organised from context to conclusion."],"weaknesses":["Occasional gaps on advanced details such as Trusted Types or activedescendant.","Few answers use a concrete example from a project you built.","Edge cases are mentioned but not worked through."],"recommendations":["Add one project example to each answer you give.","Pick one advanced technique per topic and be ready to explain it.","Try the system design category next to stretch your breadth."],"perQuestion":[{"index":0,"score":8,"feedback":"Excellent: you covered batching, reconciliation, the commit phase and the pure-render rule. Complete and well ordered.","betterAnswer":"Queue, batch, render, reconcile with keys, commit, then run effects; keep render pure."},{"index":1,"score":7.5,"feedback":"Strong: you measured before and after and chose techniques in a sensible order. Mention the cost of memo itself.","betterAnswer":"Profile, stabilise props, memoise, window the list, and verify with measurements."},{"index":2,"score":7.5,"feedback":"You explained why Context re-renders and when a store wins. Add an example of selector usage.","betterAnswer":"Use useState locally, a selector-based store for shared state, and Context for rarely changing values."},{"index":3,"score":7,"feedback":"Thorough pattern knowledge. You could mention aria-activedescendant versus roving tabindex.","betterAnswer":"Follow the listbox pattern with full keyboard support, managed focus and screen-reader testing."},{"index":4,"score":7.5,"feedback":"Good layered defence. Naming Trusted Types would round it off.","betterAnswer":"Escape by default, sanitise unavoidable HTML, strict CSP, HttpOnly cookies and dependency audits."}],"overallScore":7.4}'::jsonb, 'demo-seed', (date_trunc('day', now() at time zone 'UTC') - interval '4 days' + interval '7.5 hours' + interval '40 minutes') at time zone 'UTC');

